select sig from (select p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' sig from pg_proc p where p.pronamespace='public'::regnamespace) old_f left join (values ('get_store_subscription_public_settings(_store_id uuid)'),('get_store_template_for_seed()'),('handle_new_user()'),('has_role(_user_id uuid, _role app_role)'),('has_store_access(_store_id uuid)'),('is_landing_slug_taken(_slug text)'),('is_slug_taken(_slug text)'),('is_store_active(_store_id uuid)'),('is_store_employee(_store_id uuid)'),('is_store_owner(_store_id uuid)'),('landing_public_host(_slug text)'),('list_ai_call_tones_public()'),('list_store_pages_public(_slug text)'),('move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb)'),('next_subscription_no(_store_id uuid)'),('on_order_status_change()'),('platform_routing_hosts()'),('read_email_batch(queue_name text, batch_size integer, vt integer)'),('refresh_store_subscription_status(_store_id uuid)'),('resolve_domain(_host text)'),('resolve_host_kind(_host text)'),('seed_store_ai_agent_state(_store_id uuid)'),('staff_can(_store_id uuid, _section text, _level text)'),('staff_store_id(_user_id uuid)'),('start_trial_for_store()'),('submit_product_review(_store_id uuid, _product_id uuid, _rating smallint, _name text, _comment text, _email text, _phone text)'),('tg_block_staff_owned_store()'),('tg_invoice_template_single_default()'),('tg_low_stock_check()'),('tg_seed_store_ai_agent_state()'),('tg_staff_activity_actor_guard()'),('tg_store_customer_code()'),('tg_store_merchant_code()'),('tg_store_themes_single_default()'),('tg_store_themes_updated_at()'),('tg_stores_default_invoice_settings()'),('tg_touch_updated_at()'),('touch_landing_activity(_page_id uuid, _visit boolean)'),('touch_updated_at()'),('update_updated_at_column()'),('validate_coupon(_store_id uuid, _code text, _subtotal numeric)'),('validate_subscription_coupon(_code text, _package_id uuid, _cycle text, _amount numeric)'),('wake_messenger_job()'),('wallet_credit(_user_id uuid, _amount numeric, _type text, _invoice_id uuid, _reference text, _note text, _store_id uuid)'),('wallet_debit(_user_id uuid, _amount numeric, _type text, _invoice_id uuid, _reference text, _note text, _store_id uuid)'),('wallet_ensure(_user_id uuid, _store_id uuid)')) v(s) on v.s=old_f.sig where v.s is null;